-- GENERATED by scripts/generate-course-seed.ts (pnpm db:seed:course). Do not edit by hand.
-- Ticket 01: original demo course content in en, ja, es and ru.

create function pg_temp.section_id(sec integer) returns uuid language sql as $f$
  select s.id from public.sections s join public.courses c on c.id = s.course_id
  where c.slug = 'california-traffic-violator-course' and s.position = sec
$f$;

create function pg_temp.lesson_id(sec integer, pos integer) returns uuid language sql as $f$
  select l.id from public.lessons l where l.section_id = pg_temp.section_id(sec) and l.position = pos
$f$;

create function pg_temp.add_question(sec integer, loc text, q_text text, q_expl text, opts jsonb)
returns void language plpgsql as $f$
declare qid uuid;
begin
  insert into public.questions (section_id, locale, text, explanation)
  values (case when sec is null then null else pg_temp.section_id(sec) end, loc, q_text, q_expl)
  returning id into qid;
  insert into public.answer_options (question_id, text, is_correct)
  select qid, o ->> 'text', (o ->> 'correct')::boolean from jsonb_array_elements(opts) as o;
end
$f$;

-- Section 1
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(1), 1, 60, $q${"en":"Your responsibility behind the wheel","ja":"運転者の責任","es":"Tu responsabilidad al volante","ru":"Ваша ответственность за рулём"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(1, 1), 1, 'rich_text', $q${"en":{"markdown":"Driving is a privilege that comes with duties. You must obey traffic laws, stay alert and drive in a way that keeps everyone around you safe.\n\n- Know the rules before you start the car.\n- Adjust to the road, the weather and other people.\n- Your choices decide how a trip ends."},"ja":{"markdown":"運転は責任を伴う特権です。交通法規を守り、常に注意を払い、周囲の全員の安全を守る運転をしてください。\n\n- 出発前にルールを確認する。\n- 道路、天候、他の人に合わせて運転する。\n- あなたの判断が、移動の結果を決めます。"},"es":{"markdown":"Conducir es un privilegio con obligaciones. Debes cumplir las leyes de tránsito, estar atento y manejar de forma que todos a tu alrededor estén seguros.\n\n- Conoce las reglas antes de encender el auto.\n- Adáptate a la vía, al clima y a los demás.\n- Tus decisiones determinan cómo termina un viaje."},"ru":{"markdown":"Вождение — это привилегия, которая налагает обязанности. Соблюдайте правила, будьте внимательны и ведите машину так, чтобы все вокруг были в безопасности.\n\n- Знайте правила до начала поездки.\n- Приспосабливайтесь к дороге, погоде и другим людям.\n- Ваши решения определяют, чем закончится поездка."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(1, 1), 2, 'callout', $q${"en":{"tone":"info","title":"Tickets add up","markdown":"Traffic violations can raise your insurance cost and put points on your driving record."},"ja":{"tone":"info","title":"違反は積み重なります","markdown":"交通違反は保険料の上昇や運転記録への点数加算につながることがあります。"},"es":{"tone":"info","title":"Las infracciones se acumulan","markdown":"Las infracciones pueden subir el costo del seguro y sumar puntos a tu historial."},"ru":{"tone":"info","title":"Нарушения накапливаются","markdown":"Нарушения могут повысить стоимость страховки и добавить штрафные баллы в вашу историю."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(1, 1), 3, 'flip_card', $q${"en":{"front":"Why do traffic laws exist?","back":"To make road use predictable so that everyone can travel safely."},"ja":{"front":"交通法規はなぜあるのですか?","back":"道路の使い方を予測可能にし、全員が安全に移動できるようにするためです。"},"es":{"front":"¿Por qué existen las leyes de tránsito?","back":"Para que el uso de la vía sea predecible y todos viajen con seguridad."},"ru":{"front":"Зачем нужны правила дорожного движения?","back":"Чтобы поведение на дороге было предсказуемым и все ехали безопасно."}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(1), 2, 60, $q${"en":"Check your vehicle first","ja":"出発前の車両点検","es":"Revisa tu vehículo primero","ru":"Сначала проверьте автомобиль"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(1, 2), 1, 'image', $q${"en":{"src":"/placeholder/course/tire-check.svg","alt":"A driver checking a tire","caption":"Check tires, lights and mirrors before every trip."},"ja":{"src":"/placeholder/course/tire-check.svg","alt":"タイヤを点検する運転者","caption":"毎回の運転前にタイヤ、ライト、ミラーを確認しましょう。"},"es":{"src":"/placeholder/course/tire-check.svg","alt":"Un conductor revisa un neumático","caption":"Revisa neumáticos, luces y espejos antes de cada viaje."},"ru":{"src":"/placeholder/course/tire-check.svg","alt":"Водитель проверяет шину","caption":"Перед каждой поездкой проверяйте шины, фары и зеркала."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(1, 2), 2, 'rich_text', $q${"en":{"markdown":"A quick walk around the car takes one minute.\n\n- Tires: pressure and tread (at least 2/32 inch).\n- Lights: headlights, brake lights and signals.\n- Windows and mirrors are clean and set."},"ja":{"markdown":"車の周りを一周するのに1分もかかりません。\n\n- タイヤ: 空気圧と溝(2/32インチ以上)。\n- ライト: ヘッドライト、ブレーキランプ、ウインカー。\n- 窓とミラーはきれいで正しい位置に。"},"es":{"markdown":"Dar una vuelta al auto toma un minuto.\n\n- Neumáticos: presión y dibujo (al menos 2/32 de pulgada).\n- Luces: faros, luces de freno e intermitentes.\n- Ventanas y espejos limpios y ajustados."},"ru":{"markdown":"Осмотр автомобиля занимает минуту.\n\n- Шины: давление и протектор (не менее 2/32 дюйма).\n- Свет: фары, стоп-сигналы и поворотники.\n- Стёкла и зеркала чистые и настроены."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(1, 2), 3, 'drag_to_order', $q${"en":{"prompt":"Put the pre-drive steps in a sensible order.","items":["Walk around and check tires and lights","Adjust seat and mirrors","Fasten your seat belt","Start the engine and check the dashboard"]},"ja":{"prompt":"出発前の手順を適切な順に並べてください。","items":["車の周りを回ってタイヤとライトを確認","シートとミラーを調整","シートベルトを締める","エンジンをかけて警告灯を確認"]},"es":{"prompt":"Ordena los pasos previos a conducir.","items":["Rodear el auto y revisar neumáticos y luces","Ajustar asiento y espejos","Abrocharse el cinturón","Arrancar y revisar el tablero"]},"ru":{"prompt":"Расставьте шаги перед поездкой в разумном порядке.","items":["Обойти машину и проверить шины и свет","Настроить сиденье и зеркала","Пристегнуть ремень","Завести двигатель и проверить приборы"]}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(1), 3, 60, $q${"en":"Seat belts and child safety","ja":"シートベルトと子どもの安全","es":"Cinturones y seguridad infantil","ru":"Ремни безопасности и дети"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(1, 3), 1, 'video', $q${"en":{"title":"Why seat belts matter","captionsSrc":"/placeholder/course/captions/seat-belts.en.vtt","transcript":"In a crash, a seat belt keeps you inside the car and spreads the force across the strongest parts of your body. In California every passenger must be buckled up."},"ja":{"title":"シートベルトが大切な理由","captionsSrc":"/placeholder/course/captions/seat-belts.ja.vtt","transcript":"衝突時、シートベルトは体を車内に留め、衝撃を体の最も強い部分に分散させます。カリフォルニア州では全員の着用が必要です。"},"es":{"title":"Por qué importan los cinturones","captionsSrc":"/placeholder/course/captions/seat-belts.es.vtt","transcript":"En un choque, el cinturón te mantiene dentro del auto y reparte la fuerza en las partes más fuertes del cuerpo. En California todos los pasajeros deben usarlo."},"ru":{"title":"Почему важны ремни безопасности","captionsSrc":"/placeholder/course/captions/seat-belts.ru.vtt","transcript":"При аварии ремень удерживает вас в салоне и распределяет нагрузку на самые прочные части тела. В Калифорнии должны быть пристёгнуты все пассажиры."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(1, 3), 2, 'callout', $q${"en":{"tone":"warning","title":"Children","markdown":"Children under 2 ride rear-facing, and children under 8 sit in the back seat in a car seat or booster. Never leave a child alone in a parked car."},"ja":{"tone":"warning","title":"子ども","markdown":"2歳未満は後ろ向き、8歳未満は後部座席でチャイルドシートまたはブースターを使います。駐車中の車に子どもを残してはいけません。"},"es":{"tone":"warning","title":"Niños","markdown":"Los menores de 2 años van de espaldas y los menores de 8 en el asiento trasero con silla o elevador. Nunca dejes a un niño solo en un auto estacionado."},"ru":{"tone":"warning","title":"Дети","markdown":"Дети до 2 лет едут спиной по ходу, дети до 8 лет сидят сзади в кресле или бустере. Никогда не оставляйте ребёнка одного в припаркованной машине."}}$q$::jsonb);
