-- Section 2
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(2), 1, 60, $q${"en":"Signs, signals and markings","ja":"標識・信号・路面標示","es":"Señales, semáforos y marcas","ru":"Знаки, светофоры и разметка"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(2, 1), 1, 'rich_text', $q${"en":{"markdown":"Signs, signals and pavement markings tell you what to do.\n\n- A red light or stop sign means a full stop.\n- A flashing red light works like a stop sign.\n- A flashing yellow light means slow down and be careful.\n- A solid yellow line on your side means no passing."},"ja":{"markdown":"標識、信号、路面標示は取るべき行動を教えてくれます。\n\n- 赤信号や一時停止標識では完全に停止します。\n- 赤の点滅は一時停止と同じです。\n- 黄色の点滅は減速して注意します。\n- 自分側に黄色の実線がある場合は追い越し禁止です。"},"es":{"markdown":"Las señales, semáforos y marcas te indican qué hacer.\n\n- Luz roja o señal de alto: detención total.\n- Luz roja intermitente: funciona como un alto.\n- Luz amarilla intermitente: reduce y ten precaución.\n- Línea amarilla continua de tu lado: no adelantar."},"ru":{"markdown":"Знаки, светофоры и разметка подсказывают, что делать.\n\n- Красный сигнал или знак «Стоп» — полная остановка.\n- Мигающий красный работает как знак «Стоп».\n- Мигающий жёлтый — снизьте скорость и будьте осторожны.\n- Сплошная жёлтая линия с вашей стороны — обгон запрещён."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(2, 1), 2, 'flip_card', $q${"en":{"front":"Flashing red light","back":"Stop completely, then go when it is safe, as at a stop sign."},"ja":{"front":"赤の点滅","back":"完全に停止し、安全を確認してから進みます。"},"es":{"front":"Luz roja intermitente","back":"Detente por completo y avanza cuando sea seguro, como en un alto."},"ru":{"front":"Мигающий красный","back":"Полностью остановитесь и поезжайте, когда безопасно, как у знака «Стоп»."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(2, 1), 3, 'callout', $q${"en":{"tone":"tip","title":"Where to stop","markdown":"Stop behind the limit line. If there is none, stop before the crosswalk."},"ja":{"tone":"tip","title":"停止位置","markdown":"停止線の手前で止まります。停止線がなければ横断歩道の手前で止まります。"},"es":{"tone":"tip","title":"Dónde detenerte","markdown":"Detente detrás de la línea de alto. Si no hay, antes del cruce peatonal."},"ru":{"tone":"tip","title":"Где останавливаться","markdown":"Остановитесь перед стоп-линией. Если её нет — перед пешеходным переходом."}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(2), 2, 60, $q${"en":"Right-of-way at intersections","ja":"交差点での優先通行","es":"Derecho de paso en intersecciones","ru":"Преимущество на перекрёстках"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(2, 2), 1, 'image', $q${"en":{"src":"/placeholder/course/intersection.svg","alt":"Four cars at an intersection","caption":"Who goes first? The car that arrived first."},"ja":{"src":"/placeholder/course/intersection.svg","alt":"交差点にいる4台の車","caption":"誰が先に行く? 先に到着した車です。"},"es":{"src":"/placeholder/course/intersection.svg","alt":"Cuatro autos en una intersección","caption":"¿Quién pasa primero? El que llegó primero."},"ru":{"src":"/placeholder/course/intersection.svg","alt":"Четыре машины на перекрёстке","caption":"Кто едет первым? Тот, кто приехал первым."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(2, 2), 2, 'rich_text', $q${"en":{"markdown":"Right-of-way tells you who goes first; nobody ever owns it.\n\n- At a four-way stop, the first car to arrive goes first.\n- If two cars arrive together, the car on the right goes first.\n- Turning left, yield to oncoming traffic.\n- At an uncontrolled intersection, yield to the car on your right."},"ja":{"markdown":"優先通行権は誰が先に行くかを示すもので、誰かが「所有」するものではありません。\n\n- 四方一時停止では先に着いた車が先に進みます。\n- 同時に着いたら右側の車が先です。\n- 左折時は対向車に道を譲ります。\n- 信号のない交差点では右側の車に譲ります。"},"es":{"markdown":"El derecho de paso indica quién pasa primero; nadie lo \"posee\".\n\n- En un alto de cuatro vías pasa primero quien llegó antes.\n- Si llegan juntos, pasa el de la derecha.\n- Al girar a la izquierda, cede el paso al tráfico que viene de frente.\n- En una intersección sin control, cede al auto de tu derecha."},"ru":{"markdown":"Преимущество показывает, кто едет первым; оно никому не принадлежит.\n\n- На перекрёстке с четырьмя «Стоп» первым едет тот, кто приехал раньше.\n- Если приехали одновременно, едет тот, кто справа.\n- При левом повороте уступите встречным.\n- На нерегулируемом перекрёстке уступите машине справа."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(2, 2), 3, 'scenario', $q${"en":{"prompt":"You and another car reach a four-way stop at the same time. The other car is on your right. What do you do?","choices":[{"text":"Let the car on the right go first","feedback":"Correct: the car on the right goes first.","best":true},{"text":"Go first because you were quick","feedback":"Speed does not give you the right-of-way.","best":false},{"text":"Honk and wait","feedback":"Honking does not settle who goes first.","best":false}]},"ja":{"prompt":"別の車と同時に四方一時停止に着きました。相手は右側にいます。どうしますか?","choices":[{"text":"右の車を先に行かせる","feedback":"正解: 右側の車が先です。","best":true},{"text":"素早かったので先に行く","feedback":"速さは優先権になりません。","best":false},{"text":"クラクションを鳴らして待つ","feedback":"クラクションでは順番は決まりません。","best":false}]},"es":{"prompt":"Tú y otro auto llegan a la vez a un alto de cuatro vías. El otro está a tu derecha. ¿Qué haces?","choices":[{"text":"Dejo pasar al auto de la derecha","feedback":"Correcto: pasa primero el de la derecha.","best":true},{"text":"Paso primero porque fui rápido","feedback":"La rapidez no da derecho de paso.","best":false},{"text":"Toco la bocina y espero","feedback":"La bocina no decide quién pasa.","best":false}]},"ru":{"prompt":"Вы и другая машина одновременно подъехали к перекрёстку с четырьмя «Стоп». Она справа. Что делаете?","choices":[{"text":"Пропускаю машину справа","feedback":"Верно: первым едет машина справа.","best":true},{"text":"Еду первым, потому что быстрее","feedback":"Скорость не даёт преимущества.","best":false},{"text":"Сигналю и жду","feedback":"Гудок не решает, кто едет.","best":false}]}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(2), 3, 60, $q${"en":"Pedestrians and emergency vehicles","ja":"歩行者と緊急車両","es":"Peatones y vehículos de emergencia","ru":"Пешеходы и спецтранспорт"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(2, 3), 1, 'rich_text', $q${"en":{"markdown":"Always yield to pedestrians in a crosswalk, marked or not.\n\nWhen an emergency vehicle with siren or lights approaches, pull to the right edge of the road and stop. Never stop in an intersection."},"ja":{"markdown":"横断歩道(標示の有無を問わず)にいる歩行者には必ず道を譲ります。\n\nサイレンや赤色灯を点けた緊急車両が近づいたら、道路の右端に寄って停止します。交差点内では止まらないでください。"},"es":{"markdown":"Cede siempre el paso a los peatones en un cruce, marcado o no.\n\nSi se acerca un vehículo de emergencia con sirena o luces, oríllate a la derecha y detente. Nunca te detengas dentro de una intersección."},"ru":{"markdown":"Всегда уступайте пешеходам на переходе, размечен он или нет.\n\nЕсли приближается спецтранспорт с сиреной или мигалкой, прижмитесь к правому краю и остановитесь. Не останавливайтесь на перекрёстке."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(2, 3), 2, 'drag_to_order', $q${"en":{"prompt":"Order what to do when an ambulance approaches from behind.","items":["Notice the siren and lights","Signal and move to the right edge","Stop and wait","Resume when it has passed"]},"ja":{"prompt":"後ろから救急車が近づいたときの手順を並べてください。","items":["サイレンと赤色灯に気づく","合図して右端に寄る","停止して待つ","通過後に発進する"]},"es":{"prompt":"Ordena qué hacer si se acerca una ambulancia por detrás.","items":["Notar la sirena y las luces","Señalar y moverte a la derecha","Detenerte y esperar","Continuar cuando haya pasado"]},"ru":{"prompt":"Расставьте действия, когда сзади приближается скорая.","items":["Заметить сирену и мигалку","Включить сигнал и прижаться вправо","Остановиться и ждать","Продолжить после проезда"]}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(2, 3), 3, 'callout', $q${"en":{"tone":"warning","title":"Move over","markdown":"Approaching a stopped emergency or tow vehicle with flashing lights? Change lanes or slow down."},"ja":{"tone":"warning","title":"道を空ける","markdown":"点滅灯を点けて停車中の緊急車両やレッカー車に近づいたら、車線を変えるか減速します。"},"es":{"tone":"warning","title":"Muévete","markdown":"Si te acercas a un vehículo de emergencia o grúa detenido con luces, cambia de carril o reduce la velocidad."},"ru":{"tone":"warning","title":"Уступите дорогу","markdown":"Приближаетесь к стоящей спецмашине или эвакуатору с мигалкой? Смените полосу или сбавьте скорость."}}$q$::jsonb);
