-- Section 3
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(3), 1, 60, $q${"en":"Turning and signaling","ja":"右左折と合図","es":"Giros y señales","ru":"Повороты и сигналы"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(3, 1), 1, 'rich_text', $q${"en":{"markdown":"Signal at least 100 feet before you turn or change lanes. Slow down before the turn, not in it, and turn into the nearest lane."},"ja":{"markdown":"右左折や車線変更の少なくとも100フィート(約30m)手前で合図を出します。減速はカーブの前に済ませ、最も近い車線に入ります。"},"es":{"markdown":"Señala al menos 100 pies antes de girar o cambiar de carril. Reduce antes del giro, no durante, y entra al carril más cercano."},"ru":{"markdown":"Включайте сигнал не менее чем за 100 футов до поворота или перестроения. Сбавляйте скорость до поворота, а не в нём, и входите в ближайшую полосу."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(3, 1), 2, 'callout', $q${"en":{"tone":"tip","title":"Signal early","markdown":"Other drivers cannot read your mind. A clear signal gives them time to react."},"ja":{"tone":"tip","title":"早めの合図","markdown":"他の運転者はあなたの考えを読めません。明確な合図が反応の時間を与えます。"},"es":{"tone":"tip","title":"Señala con tiempo","markdown":"Los demás no leen tu mente. Una señal clara les da tiempo para reaccionar."},"ru":{"tone":"tip","title":"Сигнализируйте заранее","markdown":"Другие водители не читают мысли. Чёткий сигнал даёт им время среагировать."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(3, 1), 3, 'drag_to_order', $q${"en":{"prompt":"Order the steps of a safe left turn.","items":["Signal 100 feet ahead","Slow down and check for traffic","Yield to oncoming cars and pedestrians","Turn into the nearest lane"]},"ja":{"prompt":"安全な左折の手順を並べてください。","items":["100フィート手前で合図","減速して交通を確認","対向車と歩行者に譲る","最も近い車線へ曲がる"]},"es":{"prompt":"Ordena los pasos de un giro a la izquierda seguro.","items":["Señalar 100 pies antes","Reducir y revisar el tráfico","Ceder a autos y peatones","Girar al carril más cercano"]},"ru":{"prompt":"Расставьте шаги безопасного левого поворота.","items":["Включить сигнал за 100 футов","Снизить скорость и осмотреться","Уступить встречным и пешеходам","Повернуть в ближайшую полосу"]}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(3), 2, 60, $q${"en":"Changing lanes and merging","ja":"車線変更と合流","es":"Cambio de carril e incorporación","ru":"Перестроение и слияние"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(3, 2), 1, 'rich_text', $q${"en":{"markdown":"Before changing lanes: mirror, signal, then look over your shoulder to check the blind spot. When merging onto a freeway, match the speed of traffic and find a gap."},"ja":{"markdown":"車線変更の前に、ミラーを見て、合図を出し、肩越しに死角を確認します。高速道路に合流するときは流れの速度に合わせ、空きを見つけます。"},"es":{"markdown":"Antes de cambiar de carril: espejo, señal y mira por encima del hombro el punto ciego. Al incorporarte a una autopista, iguala la velocidad del tráfico y busca un hueco."},"ru":{"markdown":"Перед перестроением: зеркало, сигнал, затем взгляд через плечо на слепую зону. При въезде на шоссе уравняйте скорость с потоком и найдите просвет."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(3, 2), 2, 'scenario', $q${"en":{"prompt":"You are on a freeway on-ramp and traffic flows at 65 mph. What should you do?","choices":[{"text":"Accelerate to match traffic and merge into a gap","feedback":"Right: merge at the speed of traffic.","best":true},{"text":"Stop at the end of the ramp","feedback":"Stopping on a ramp is dangerous.","best":false},{"text":"Merge slowly at 30 mph","feedback":"Too slow: it forces others to brake.","best":false}]},"ja":{"prompt":"高速道路の入口で、流れは時速65マイルです。どうしますか?","choices":[{"text":"流れに合わせて加速し空きに合流","feedback":"正解: 流れの速度で合流します。","best":true},{"text":"ランプの終わりで停止","feedback":"ランプでの停止は危険です。","best":false},{"text":"時速30マイルでゆっくり合流","feedback":"遅すぎて他の車が急ブレーキを踏みます。","best":false}]},"es":{"prompt":"Estás en una rampa de incorporación y el tráfico va a 65 mph. ¿Qué haces?","choices":[{"text":"Acelero a la velocidad del tráfico y entro en un hueco","feedback":"Bien: incorpórate a la velocidad del tráfico.","best":true},{"text":"Me detengo al final de la rampa","feedback":"Detenerse en la rampa es peligroso.","best":false},{"text":"Me incorporo despacio a 30 mph","feedback":"Muy lento: obliga a otros a frenar.","best":false}]},"ru":{"prompt":"Вы на въезде на шоссе, поток идёт 65 миль/ч. Что делать?","choices":[{"text":"Разгоняюсь до скорости потока и вливаюсь в просвет","feedback":"Верно: сливайтесь на скорости потока.","best":true},{"text":"Останавливаюсь в конце съезда","feedback":"Остановка на съезде опасна.","best":false},{"text":"Вливаюсь медленно на 30 миль/ч","feedback":"Слишком медленно: другим придётся тормозить.","best":false}]}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(3, 2), 3, 'flip_card', $q${"en":{"front":"Blind spot","back":"The area beside and behind your car that mirrors do not show. Look over your shoulder."},"ja":{"front":"死角","back":"ミラーに映らない車の横や斜め後ろの範囲。肩越しに確認します。"},"es":{"front":"Punto ciego","back":"La zona al lado y atrás que los espejos no muestran. Mira por encima del hombro."},"ru":{"front":"Слепая зона","back":"Область сбоку и сзади, которую не показывают зеркала. Смотрите через плечо."}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(3), 3, 60, $q${"en":"Parking and backing up","ja":"駐車とバック","es":"Estacionamiento y reversa","ru":"Парковка и задний ход"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(3, 3), 1, 'rich_text', $q${"en":{"markdown":"Do not park within 15 feet of a fire hydrant. On a hill facing down, turn your wheels toward the curb; facing up with a curb, turn them away from it. Set the parking brake."},"ja":{"markdown":"消火栓から15フィート(約4.5m)以内には駐車しません。下り坂では前輪を縁石側に、縁石のある上り坂では縁石と反対に向けます。パーキングブレーキをかけます。"},"es":{"markdown":"No estaciones a menos de 15 pies de un hidrante. En bajada gira las ruedas hacia la acera; en subida con acera, aléjalas. Pon el freno de mano."},"ru":{"markdown":"Не паркуйтесь ближе 15 футов к гидранту. На спуске поверните колёса к бордюру; на подъёме при бордюре — от него. Включите ручной тормоз."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(3, 3), 2, 'callout', $q${"en":{"tone":"warning","title":"Look behind","markdown":"Before backing up, check behind the car, not only the camera. Back slowly."},"ja":{"tone":"warning","title":"後方確認","markdown":"バックの前にカメラだけでなく車の後ろを直接確認し、ゆっくり下がります。"},"es":{"tone":"warning","title":"Mira atrás","markdown":"Antes de retroceder revisa detrás del auto, no solo la cámara. Ve despacio."},"ru":{"tone":"warning","title":"Смотрите назад","markdown":"Перед задним ходом осмотрите пространство позади, а не только камеру. Двигайтесь медленно."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(3, 3), 3, 'flip_card', $q${"en":{"front":"Distance from a fire hydrant","back":"Keep at least 15 feet."},"ja":{"front":"消火栓からの距離","back":"15フィート以上離します。"},"es":{"front":"Distancia a un hidrante","back":"Mantén al menos 15 pies."},"ru":{"front":"Расстояние до гидранта","back":"Не менее 15 футов."}}$q$::jsonb);
