-- Section 4
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(4), 1, 60, $q${"en":"The three-second rule","ja":"3秒ルール","es":"La regla de los tres segundos","ru":"Правило трёх секунд"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(4, 1), 1, 'image', $q${"en":{"src":"/placeholder/course/following-distance.svg","alt":"Two cars with a gap between them","caption":"Leave at least three seconds behind the car ahead."},"ja":{"src":"/placeholder/course/following-distance.svg","alt":"間隔を空けた2台の車","caption":"前の車との間に3秒以上空けましょう。"},"es":{"src":"/placeholder/course/following-distance.svg","alt":"Dos autos con distancia entre ellos","caption":"Deja al menos tres segundos detrás del auto de adelante."},"ru":{"src":"/placeholder/course/following-distance.svg","alt":"Две машины с дистанцией между ними","caption":"Держите не менее трёх секунд до машины впереди."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(4, 1), 2, 'rich_text', $q${"en":{"markdown":"Pick a fixed object ahead. When the car in front passes it, count \"one-thousand-one, one-thousand-two, one-thousand-three\". If you pass it before you finish, you are too close. Add more time in rain, fog or at night."},"ja":{"markdown":"前方の固定物を選び、前の車がそこを通過したら「いち、に、さん」と数えます。数え終える前に自分が通過したら近すぎます。雨、霧、夜間は時間を増やします。"},"es":{"markdown":"Elige un objeto fijo adelante. Cuando el auto de enfrente lo pase, cuenta \"mil uno, mil dos, mil tres\". Si lo pasas antes de terminar, estás muy cerca. Aumenta el tiempo con lluvia, niebla o de noche."},"ru":{"markdown":"Выберите неподвижный предмет впереди. Когда машина впереди проедет его, считайте «раз-тысяча, два-тысяча, три-тысяча». Если вы доехали раньше, дистанция мала. В дождь, туман и ночью увеличьте время."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(4, 1), 3, 'flip_card', $q${"en":{"front":"Safe following distance","back":"At least 3 seconds, more in bad conditions."},"ja":{"front":"安全な車間距離","back":"最低3秒。悪条件ではさらに長く。"},"es":{"front":"Distancia segura","back":"Al menos 3 segundos, más en malas condiciones."},"ru":{"front":"Безопасная дистанция","back":"Не менее 3 секунд, в плохих условиях — больше."}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(4), 2, 60, $q${"en":"Scan and predict","ja":"見渡して予測する","es":"Observa y anticipa","ru":"Осматривайтесь и прогнозируйте"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(4, 2), 1, 'video', $q${"en":{"title":"Looking 12 seconds ahead","captionsSrc":"/placeholder/course/captions/scanning.en.vtt","transcript":"Look far down the road, about 12 seconds ahead. Check your mirrors every 5 to 8 seconds. Watch for brake lights, children near the road and cars waiting to pull out."},"ja":{"title":"12秒先を見る","captionsSrc":"/placeholder/course/captions/scanning.ja.vtt","transcript":"道路の遠く、約12秒先を見ます。5〜8秒ごとにミラーを確認します。ブレーキランプ、道路脇の子ども、発進を待つ車に注意します。"},"es":{"title":"Mirar 12 segundos adelante","captionsSrc":"/placeholder/course/captions/scanning.es.vtt","transcript":"Mira lejos, unos 12 segundos adelante. Revisa los espejos cada 5 a 8 segundos. Atento a luces de freno, niños junto a la vía y autos por salir."},"ru":{"title":"Взгляд на 12 секунд вперёд","captionsSrc":"/placeholder/course/captions/scanning.ru.vtt","transcript":"Смотрите далеко, примерно на 12 секунд вперёд. Проверяйте зеркала каждые 5–8 секунд. Следите за стоп-сигналами, детьми у дороги и машинами, готовыми выехать."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(4, 2), 2, 'scenario', $q${"en":{"prompt":"A ball rolls into the street from between parked cars. What do you do?","choices":[{"text":"Slow down and be ready to stop for a child","feedback":"Right: a child often follows the ball.","best":true},{"text":"Keep your speed","feedback":"Risky: you may not stop in time.","best":false},{"text":"Honk and speed up","feedback":"Never speed up toward a hazard.","best":false}]},"ja":{"prompt":"駐車車両の間からボールが道路に転がってきました。どうしますか?","choices":[{"text":"減速し、子どもに備えて停止できる状態に","feedback":"正解: ボールの後に子どもが来ることがよくあります。","best":true},{"text":"速度を保つ","feedback":"危険です。止まれないかもしれません。","best":false},{"text":"クラクションを鳴らして加速","feedback":"危険に向かって加速してはいけません。","best":false}]},"es":{"prompt":"Una pelota rueda a la calle entre autos estacionados. ¿Qué haces?","choices":[{"text":"Reduzco y me preparo para frenar por un niño","feedback":"Bien: a menudo un niño sigue la pelota.","best":true},{"text":"Mantengo la velocidad","feedback":"Riesgoso: quizá no alcances a frenar.","best":false},{"text":"Toco la bocina y acelero","feedback":"Nunca aceleres hacia un peligro.","best":false}]},"ru":{"prompt":"Мяч выкатился на дорогу между припаркованными машинами. Что делаете?","choices":[{"text":"Сбавляю скорость и готов остановиться из-за ребёнка","feedback":"Верно: за мячом часто выбегает ребёнок.","best":true},{"text":"Сохраняю скорость","feedback":"Опасно: можете не успеть затормозить.","best":false},{"text":"Сигналю и ускоряюсь","feedback":"Никогда не ускоряйтесь навстречу опасности.","best":false}]}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(4, 2), 3, 'callout', $q${"en":{"tone":"tip","title":"Leave yourself an out","markdown":"Keep space around your car so you have somewhere to go if something goes wrong."},"ja":{"tone":"tip","title":"逃げ道を残す","markdown":"何かあったときに逃げられるよう、車の周りに余裕を保ちます。"},"es":{"tone":"tip","title":"Deja una salida","markdown":"Mantén espacio alrededor para tener adónde ir si algo sale mal."},"ru":{"tone":"tip","title":"Оставляйте запасной путь","markdown":"Сохраняйте свободное место вокруг, чтобы было куда деться."}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(4), 3, 60, $q${"en":"Handling aggressive drivers","ja":"あおり運転への対処","es":"Cómo tratar a conductores agresivos","ru":"Агрессивные водители"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(4, 3), 1, 'rich_text', $q${"en":{"markdown":"If another driver is aggressive, do not respond. Stay calm, give them room, avoid eye contact and never brake-check. If you feel unsafe, drive to a public place and call 911."},"ja":{"markdown":"他の運転者が攻撃的でも反応しないでください。落ち着いて道を譲り、目を合わせず、わざと急ブレーキをかけないこと。身の危険を感じたら人の多い場所へ行き、911に通報します。"},"es":{"markdown":"Si otro conductor es agresivo, no respondas. Mantén la calma, dale espacio, evita el contacto visual y nunca frenes para molestarlo. Si te sientes en peligro, ve a un lugar público y llama al 911."},"ru":{"markdown":"Если другой водитель агрессивен, не отвечайте. Сохраняйте спокойствие, уступите дорогу, избегайте зрительного контакта и не тормозите демонстративно. Если вам опасно, поезжайте в людное место и звоните 911."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(4, 3), 2, 'drag_to_order', $q${"en":{"prompt":"Order your response to an aggressive driver.","items":["Stay calm and give space","Do not make gestures or eye contact","Drive to a public place","Call 911 if you feel unsafe"]},"ja":{"prompt":"攻撃的な運転者への対応を並べてください。","items":["落ち着いて間隔を空ける","ジェスチャーや視線を避ける","人の多い場所へ向かう","危険なら911に通報"]},"es":{"prompt":"Ordena tu respuesta a un conductor agresivo.","items":["Mantener la calma y dar espacio","Evitar gestos y contacto visual","Ir a un lugar público","Llamar al 911 si te sientes en peligro"]},"ru":{"prompt":"Расставьте ваши действия при агрессивном водителе.","items":["Сохранить спокойствие и дать место","Не жестикулировать, не смотреть","Поехать в людное место","Позвонить 911, если опасно"]}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(4, 3), 3, 'callout', $q${"en":{"tone":"warning","title":"Do not retaliate","markdown":"Road rage can turn a small mistake into a crime."},"ja":{"tone":"warning","title":"仕返しはしない","markdown":"ロードレイジは小さなミスを犯罪に変えかねません。"},"es":{"tone":"warning","title":"No tomes represalias","markdown":"La furia vial puede convertir un error pequeño en un delito."},"ru":{"tone":"warning","title":"Не мстите","markdown":"Дорожная агрессия может превратить мелкую ошибку в преступление."}}$q$::jsonb);
