-- Section 5
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(5), 1, 60, $q${"en":"Speed limits","ja":"速度制限","es":"Límites de velocidad","ru":"Ограничения скорости"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(5, 1), 1, 'rich_text', $q${"en":{"markdown":"The basic speed law: never drive faster than is safe for the conditions, even below the posted limit. Near schools the limit is 25 mph when children are outside or crossing. Residential and business districts are 25 mph unless signs say otherwise."},"ja":{"markdown":"基本速度の原則: 制限速度以下でも、状況に対して安全な速度を超えてはいけません。学校付近では、子どもが外にいるか横断中なら時速25マイルです。住宅街や商業地域は標識がなければ時速25マイルです。"},"es":{"markdown":"La ley de velocidad básica: nunca manejes más rápido de lo seguro para las condiciones, aunque estés bajo el límite. Cerca de escuelas el límite es 25 mph cuando hay niños afuera o cruzando. Zonas residenciales y comerciales: 25 mph salvo que las señales digan otra cosa."},"ru":{"markdown":"Основное правило скорости: никогда не ехать быстрее, чем безопасно в данных условиях, даже ниже знака. У школ — 25 миль/ч, когда дети на улице или переходят дорогу. В жилых и деловых районах — 25 миль/ч, если нет других знаков."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(5, 1), 2, 'flip_card', $q${"en":{"front":"School zone limit","back":"25 mph when children are present."},"ja":{"front":"スクールゾーンの制限","back":"子どもがいるときは時速25マイル。"},"es":{"front":"Límite en zona escolar","back":"25 mph cuando hay niños."},"ru":{"front":"Скорость у школы","back":"25 миль/ч, когда рядом дети."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(5, 1), 3, 'callout', $q${"en":{"tone":"info","title":"Speed and stopping","markdown":"The faster you go, the longer it takes to stop. Doubling speed roughly quadruples braking distance."},"ja":{"tone":"info","title":"速度と停止距離","markdown":"速度が上がるほど停止に時間がかかります。速度が2倍になると制動距離はおよそ4倍です。"},"es":{"tone":"info","title":"Velocidad y frenado","markdown":"A mayor velocidad, más distancia para frenar. Al duplicar la velocidad, el frenado se cuadruplica aproximadamente."},"ru":{"tone":"info","title":"Скорость и торможение","markdown":"Чем выше скорость, тем длиннее остановка. Удвоение скорости увеличивает тормозной путь примерно вчетверо."}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(5), 2, 60, $q${"en":"Rain, fog and slippery roads","ja":"雨・霧・滑りやすい路面","es":"Lluvia, niebla y caminos resbalosos","ru":"Дождь, туман и скользкая дорога"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(5, 2), 1, 'rich_text', $q${"en":{"markdown":"The first rain makes roads slick because oil rises. Slow down, increase your following distance and turn on headlights when wipers are on. In fog use low beams. If you start to hydroplane, ease off the gas and steer straight."},"ja":{"markdown":"雨の降り始めは油が浮き、路面が滑りやすくなります。減速し、車間距離を広げ、ワイパー使用時はヘッドライトを点けます。霧ではロービームを使います。ハイドロプレーニングが起きたらアクセルを緩め、まっすぐ保ちます。"},"es":{"markdown":"La primera lluvia deja el camino resbaloso porque sube el aceite. Reduce, aumenta la distancia y enciende los faros cuando uses limpiaparabrisas. Con niebla usa luces bajas. Si pierdes tracción por hidroplaneo, suelta el acelerador y mantén el volante recto."},"ru":{"markdown":"Первый дождь делает дорогу скользкой — выступает масло. Сбавьте скорость, увеличьте дистанцию и включите фары при работе дворников. В тумане используйте ближний свет. При аквапланировании отпустите газ и держите руль прямо."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(5, 2), 2, 'scenario', $q${"en":{"prompt":"Your car starts to hydroplane on a wet highway. What do you do?","choices":[{"text":"Ease off the gas and steer straight","feedback":"Right: let the tires regain grip.","best":true},{"text":"Brake hard","feedback":"Hard braking can cause a skid.","best":false},{"text":"Turn the wheel sharply","feedback":"Sharp steering can spin the car.","best":false}]},"ja":{"prompt":"濡れた幹線道路で車がハイドロプレーニングを起こしました。どうしますか?","choices":[{"text":"アクセルを緩めまっすぐ保つ","feedback":"正解: タイヤがグリップを取り戻すのを待ちます。","best":true},{"text":"急ブレーキをかける","feedback":"急ブレーキはスリップを招きます。","best":false},{"text":"ハンドルを急に切る","feedback":"急ハンドルは車を回転させます。","best":false}]},"es":{"prompt":"Tu auto empieza a hidroplanear en una carretera mojada. ¿Qué haces?","choices":[{"text":"Suelto el acelerador y mantengo el volante recto","feedback":"Bien: deja que los neumáticos recuperen agarre.","best":true},{"text":"Freno fuerte","feedback":"Frenar fuerte puede causar derrape.","best":false},{"text":"Giro el volante bruscamente","feedback":"Girar de golpe puede hacer girar el auto.","best":false}]},"ru":{"prompt":"Машина начала аквапланировать на мокрой трассе. Что делать?","choices":[{"text":"Отпускаю газ и держу руль прямо","feedback":"Верно: дайте шинам восстановить сцепление.","best":true},{"text":"Резко торможу","feedback":"Резкое торможение вызовет занос.","best":false},{"text":"Резко кручу руль","feedback":"Резкий поворот руля раскрутит машину.","best":false}]}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(5, 2), 3, 'drag_to_order', $q${"en":{"prompt":"Order the steps when rain begins.","items":["Turn on wipers","Turn on headlights","Slow down","Increase following distance"]},"ja":{"prompt":"雨が降り始めたときの手順を並べてください。","items":["ワイパーを作動","ヘッドライトを点灯","減速する","車間距離を広げる"]},"es":{"prompt":"Ordena los pasos cuando empieza a llover.","items":["Encender el limpiaparabrisas","Encender los faros","Reducir la velocidad","Aumentar la distancia"]},"ru":{"prompt":"Расставьте шаги, когда начинается дождь.","items":["Включить дворники","Включить фары","Сбавить скорость","Увеличить дистанцию"]}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(5), 3, 60, $q${"en":"Driving at night","ja":"夜間の運転","es":"Conducir de noche","ru":"Вождение ночью"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(5, 3), 1, 'rich_text', $q${"en":{"markdown":"Use headlights from 30 minutes after sunset to 30 minutes before sunrise. Dim your high beams for oncoming cars and when following another vehicle. Do not overdrive your headlights: you must be able to stop within the distance you can see."},"ja":{"markdown":"日没30分後から日の出30分前までヘッドライトを点けます。対向車や前の車に続くときはハイビームを切り替えます。ライトの届く範囲内で止まれる速度で走ります。"},"es":{"markdown":"Usa los faros desde 30 minutos después del atardecer hasta 30 minutos antes del amanecer. Baja las luces altas con autos de frente o al seguir a otro. Debes poder frenar dentro de la distancia que alcanzas a ver."},"ru":{"markdown":"Включайте фары через 30 минут после заката и до 30 минут до рассвета. Переключайтесь на ближний свет для встречных и при движении за другой машиной. Скорость должна позволять остановиться в пределах видимости."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(5, 3), 2, 'flip_card', $q${"en":{"front":"When must headlights be on?","back":"From 30 min after sunset to 30 min before sunrise, and when wipers are on."},"ja":{"front":"ヘッドライトはいつ点けますか?","back":"日没30分後〜日の出30分前、およびワイパー使用時。"},"es":{"front":"¿Cuándo deben estar encendidos los faros?","back":"De 30 min después del atardecer a 30 min antes del amanecer y con limpiaparabrisas."},"ru":{"front":"Когда включать фары?","back":"С 30 минут после заката до 30 минут до рассвета и при работе дворников."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(5, 3), 3, 'callout', $q${"en":{"tone":"tip","title":"Glare","markdown":"If an oncoming car's lights dazzle you, look toward the right edge of the road."},"ja":{"tone":"tip","title":"まぶしさ","markdown":"対向車のライトがまぶしいときは、道路の右端を見ます。"},"es":{"tone":"tip","title":"Deslumbramiento","markdown":"Si las luces de enfrente te deslumbran, mira hacia el borde derecho."},"ru":{"tone":"tip","title":"Блики","markdown":"Если встречные фары слепят, смотрите на правый край дороги."}}$q$::jsonb);
