-- Section 6
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(6), 1, 60, $q${"en":"Alcohol and driving","ja":"飲酒運転","es":"Alcohol y conducción","ru":"Алкоголь и вождение"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(6, 1), 1, 'rich_text', $q${"en":{"markdown":"In California it is illegal to drive with a blood alcohol concentration (BAC) of 0.08% or more. For drivers under 21 the limit is 0.01%. Even below the limit, alcohol slows reaction time and blurs judgment."},"ja":{"markdown":"カリフォルニア州では血中アルコール濃度(BAC)0.08%以上での運転は違法です。21歳未満は0.01%です。制限値以下でも、アルコールは反応を遅らせ判断を鈍らせます。"},"es":{"markdown":"En California es ilegal manejar con una concentración de alcohol en sangre (BAC) de 0.08% o más. Para menores de 21 años el límite es 0.01%. Incluso por debajo, el alcohol retrasa los reflejos y nubla el juicio."},"ru":{"markdown":"В Калифорнии запрещено ездить с концентрацией алкоголя в крови (BAC) 0,08% и выше. Для водителей до 21 года предел — 0,01%. Даже ниже предела алкоголь замедляет реакцию и ухудшает суждение."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(6, 1), 2, 'flip_card', $q${"en":{"front":"Adult BAC limit","back":"0.08% (0.01% under 21)."},"ja":{"front":"成人のBAC上限","back":"0.08%(21歳未満は0.01%)。"},"es":{"front":"Límite de BAC para adultos","back":"0.08% (0.01% bajo 21)."},"ru":{"front":"Предел BAC для взрослых","back":"0,08% (0,01% до 21 года)."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(6, 1), 3, 'callout', $q${"en":{"tone":"warning","title":"Myths","markdown":"Coffee, cold showers and fresh air do not sober you up. Only time does."},"ja":{"tone":"warning","title":"よくある誤解","markdown":"コーヒー、冷たいシャワー、外の空気では酔いは醒めません。時間だけが解決します。"},"es":{"tone":"warning","title":"Mitos","markdown":"El café, la ducha fría y el aire fresco no te quitan la borrachera. Solo el tiempo."},"ru":{"tone":"warning","title":"Мифы","markdown":"Кофе, холодный душ и свежий воздух не отрезвляют. Помогает только время."}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(6), 2, 60, $q${"en":"Drugs and medication","ja":"薬物と医薬品","es":"Drogas y medicamentos","ru":"Наркотики и лекарства"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(6, 2), 1, 'video', $q${"en":{"title":"Medicine and driving","captionsSrc":"/placeholder/course/captions/medication.en.vtt","transcript":"Many prescription and over-the-counter medicines cause drowsiness. Read the label. It is illegal to drive impaired by any drug, including legal ones. Never drive after using cannabis. Keep any open container of alcohol or cannabis out of the passenger area."},"ja":{"title":"薬と運転","captionsSrc":"/placeholder/course/captions/medication.ja.vtt","transcript":"多くの処方薬や市販薬は眠気を引き起こします。ラベルを読みましょう。合法の薬を含め、薬物の影響下での運転は違法です。大麻使用後は運転しないでください。開封済みのアルコールや大麻は車内の乗員スペースに置かないでください。"},"es":{"title":"Medicinas y conducción","captionsSrc":"/placeholder/course/captions/medication.es.vtt","transcript":"Muchos medicamentos con receta y de venta libre causan somnolencia. Lee la etiqueta. Es ilegal manejar bajo el efecto de cualquier droga, incluso legal. Nunca manejes tras consumir cannabis. Mantén fuera del habitáculo cualquier envase abierto de alcohol o cannabis."},"ru":{"title":"Лекарства и вождение","captionsSrc":"/placeholder/course/captions/medication.ru.vtt","transcript":"Многие рецептурные и безрецептурные лекарства вызывают сонливость. Читайте этикетку. Ездить под действием любых веществ, даже разрешённых, нельзя. Не садитесь за руль после каннабиса. Открытые ёмкости с алкоголем или каннабисом не держите в салоне."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(6, 2), 2, 'scenario', $q${"en":{"prompt":"Your allergy pill label says it may cause drowsiness. You must drive in an hour. What should you do?","choices":[{"text":"Do not take it or find another ride","feedback":"Right: safe choice.","best":true},{"text":"Take it and drive carefully","feedback":"Careful driving does not cancel drowsiness.","best":false},{"text":"Drink coffee after","feedback":"Coffee does not fully offset it.","best":false}]},"ja":{"prompt":"アレルギー薬のラベルに眠気の恐れがあると書かれています。1時間後に運転が必要です。どうしますか?","choices":[{"text":"服用しない、または別の移動手段を探す","feedback":"正解: 安全な選択です。","best":true},{"text":"服用して慎重に運転","feedback":"慎重に運転しても眠気は消えません。","best":false},{"text":"その後コーヒーを飲む","feedback":"コーヒーでは完全に打ち消せません。","best":false}]},"es":{"prompt":"La etiqueta de tu antialérgico dice que puede causar somnolencia. Debes manejar en una hora. ¿Qué haces?","choices":[{"text":"No lo tomo o busco otro transporte","feedback":"Bien: opción segura.","best":true},{"text":"Lo tomo y manejo con cuidado","feedback":"Manejar con cuidado no quita la somnolencia.","best":false},{"text":"Tomo café después","feedback":"El café no lo compensa del todo.","best":false}]},"ru":{"prompt":"На этикетке антигистаминного указана сонливость. Через час вам ехать. Что делать?","choices":[{"text":"Не принимаю или нахожу другой транспорт","feedback":"Верно: безопасный выбор.","best":true},{"text":"Принимаю и еду осторожно","feedback":"Осторожность не уберёт сонливость.","best":false},{"text":"Пью кофе после","feedback":"Кофе не компенсирует полностью.","best":false}]}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(6, 2), 3, 'drag_to_order', $q${"en":{"prompt":"Order the steps before driving after taking medication.","items":["Read the label","Check for drowsiness warnings","Ask a pharmacist if unsure","Decide whether to drive"]},"ja":{"prompt":"服薬後に運転する前の手順を並べてください。","items":["ラベルを読む","眠気の警告を確認","不明なら薬剤師に相談","運転するか判断"]},"es":{"prompt":"Ordena los pasos antes de manejar tras tomar un medicamento.","items":["Leer la etiqueta","Buscar advertencias de somnolencia","Preguntar al farmacéutico si hay dudas","Decidir si manejas"]},"ru":{"prompt":"Расставьте шаги перед поездкой после приёма лекарства.","items":["Прочитать этикетку","Найти предупреждения о сонливости","Спросить фармацевта при сомнении","Решить, садиться ли за руль"]}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(6), 3, 60, $q${"en":"Drowsy driving","ja":"居眠り運転","es":"Manejar con sueño","ru":"Сонное вождение"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(6, 3), 1, 'rich_text', $q${"en":{"markdown":"Fatigue slows reactions like alcohol does. Warning signs: yawning, heavy eyelids, drifting from your lane. The only cure is sleep. If you feel drowsy, pull over in a safe place and rest."},"ja":{"markdown":"疲労はアルコールと同様に反応を遅らせます。あくび、まぶたが重い、車線からふらつくなどが兆候です。解決策は睡眠だけです。眠気を感じたら安全な場所に停車して休みます。"},"es":{"markdown":"La fatiga retrasa los reflejos como el alcohol. Señales: bostezos, párpados pesados, salirte del carril. La única cura es dormir. Si tienes sueño, detente en un lugar seguro y descansa."},"ru":{"markdown":"Усталость замедляет реакцию, как алкоголь. Признаки: зевота, тяжёлые веки, снос с полосы. Лечится только сном. Если клонит в сон, остановитесь в безопасном месте и отдохните."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(6, 3), 2, 'flip_card', $q${"en":{"front":"Best cure for drowsiness","back":"Sleep. Pull over safely and rest."},"ja":{"front":"眠気の最良の対処","back":"睡眠。安全に停車して休む。"},"es":{"front":"Mejor cura para la somnolencia","back":"Dormir. Detente con seguridad y descansa."},"ru":{"front":"Лучшее средство от сонливости","back":"Сон. Безопасно остановитесь и отдохните."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(6, 3), 3, 'callout', $q${"en":{"tone":"tip","title":"Plan long trips","markdown":"Stop every two hours, sleep well before you leave and share driving when you can."},"ja":{"tone":"tip","title":"長距離は計画的に","markdown":"2時間ごとに休憩し、出発前によく眠り、可能なら運転を交代します。"},"es":{"tone":"tip","title":"Planea los viajes largos","markdown":"Haz paradas cada dos horas, duerme bien antes y turna el manejo."},"ru":{"tone":"tip","title":"Планируйте дальние поездки","markdown":"Останавливайтесь каждые два часа, хорошо выспитесь и меняйтесь за рулём."}}$q$::jsonb);
