-- Section 7
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(7), 1, 60, $q${"en":"Distracted driving","ja":"ながら運転","es":"Conducción distraída","ru":"Отвлечение за рулём"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(7, 1), 1, 'rich_text', $q${"en":{"markdown":"California's hands-free law: you may not hold a phone or other device while driving. Use a mount and voice commands, and touch the screen only once with a single tap or swipe. Texting takes your eyes off the road for about five seconds, the length of a football field at highway speed."},"ja":{"markdown":"カリフォルニア州のハンズフリー法: 運転中にスマートフォンなどを手に持ってはいけません。ホルダーと音声操作を使い、画面操作は1回のタップかスワイプだけにします。メールを打つと約5秒間目を離すことになり、高速では約100m進みます。"},"es":{"markdown":"La ley de manos libres de California: no puedes sostener un teléfono u otro dispositivo al manejar. Usa un soporte y comandos de voz, y toca la pantalla solo una vez. Escribir un mensaje te quita la vista del camino unos cinco segundos, la longitud de una cancha de fútbol a velocidad de autopista."},"ru":{"markdown":"Закон Калифорнии о hands-free: нельзя держать телефон или другое устройство в руках за рулём. Используйте держатель и голосовые команды, касайтесь экрана один раз. Сообщение отвлекает на пять секунд — это длина футбольного поля на скорости шоссе."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(7, 1), 2, 'callout', $q${"en":{"tone":"warning","title":"Not only phones","markdown":"Eating, grooming and reaching for objects also take your attention. Finish before you drive."},"ja":{"tone":"warning","title":"スマホだけではない","markdown":"食事、身だしなみ、物を取ることも注意をそらします。運転前に済ませましょう。"},"es":{"tone":"warning","title":"No solo teléfonos","markdown":"Comer, arreglarte o buscar objetos también distrae. Termina antes de manejar."},"ru":{"tone":"warning","title":"Не только телефоны","markdown":"Еда, макияж и поиск вещей тоже отвлекают. Закончите до начала поездки."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(7, 1), 3, 'scenario', $q${"en":{"prompt":"A message pops up on your phone while you drive. What do you do?","choices":[{"text":"Leave it until I park","feedback":"Right: it can wait.","best":true},{"text":"Read it at a red light","feedback":"Still illegal while holding the phone.","best":false},{"text":"Reply quickly with one hand","feedback":"Illegal and dangerous.","best":false}]},"ja":{"prompt":"運転中にスマホにメッセージが届きました。どうしますか?","choices":[{"text":"駐車するまで放置","feedback":"正解: 後で大丈夫です。","best":true},{"text":"赤信号で読む","feedback":"手に持てば違法です。","best":false},{"text":"片手でさっと返信","feedback":"違法で危険です。","best":false}]},"es":{"prompt":"Te llega un mensaje mientras manejas. ¿Qué haces?","choices":[{"text":"Lo dejo hasta estacionar","feedback":"Bien: puede esperar.","best":true},{"text":"Lo leo en un semáforo","feedback":"Sigue siendo ilegal si sostienes el teléfono.","best":false},{"text":"Respondo rápido con una mano","feedback":"Ilegal y peligroso.","best":false}]},"ru":{"prompt":"Во время езды пришло сообщение. Что делаете?","choices":[{"text":"Оставляю до остановки","feedback":"Верно: подождёт.","best":true},{"text":"Читаю на красном","feedback":"Всё равно нельзя держать телефон.","best":false},{"text":"Быстро отвечаю одной рукой","feedback":"Незаконно и опасно.","best":false}]}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(7), 2, 60, $q${"en":"Pedestrians and bicyclists","ja":"歩行者と自転車","es":"Peatones y ciclistas","ru":"Пешеходы и велосипедисты"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(7, 2), 1, 'rich_text', $q${"en":{"markdown":"Give bicyclists at least 3 feet when passing. Bicyclists may use the full lane when it is too narrow to share. Before turning right, check for cyclists in the bike lane and merge into it only as the law allows. Watch for people in wheelchairs and for blind pedestrians with a white cane."},"ja":{"markdown":"自転車を追い越すときは少なくとも3フィート(約90cm)空けます。車線が狭くて並走できない場合、自転車は車線全体を使えます。右折前に自転車レーンの自転車を確認します。車いすの人や白杖の視覚障害者にも注意します。"},"es":{"markdown":"Da al menos 3 pies a los ciclistas al rebasar. Pueden usar todo el carril si es muy angosto para compartirlo. Antes de girar a la derecha revisa ciclistas en el carril bici. Atento a personas en silla de ruedas y a peatones ciegos con bastón blanco."},"ru":{"markdown":"Обгоняя велосипедиста, оставляйте не менее 3 футов. Если полоса слишком узка, он может занять её целиком. Перед правым поворотом проверьте велосипедистов на велодорожке. Следите за людьми в инвалидных колясках и незрячими с белой тростью."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(7, 2), 2, 'flip_card', $q${"en":{"front":"Passing a bicyclist","back":"Leave at least 3 feet."},"ja":{"front":"自転車の追い越し","back":"3フィート以上空ける。"},"es":{"front":"Rebasar a un ciclista","back":"Deja al menos 3 pies."},"ru":{"front":"Обгон велосипедиста","back":"Оставьте не менее 3 футов."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(7, 2), 3, 'drag_to_order', $q${"en":{"prompt":"Order the steps to pass a bicyclist safely.","items":["Slow down and check traffic behind","Signal and check oncoming lane","Pass leaving 3 feet","Return to the lane when clear"]},"ja":{"prompt":"自転車を安全に追い越す手順を並べてください。","items":["減速して後方を確認","合図し対向車線を確認","3フィート空けて追い越す","安全になったら車線に戻る"]},"es":{"prompt":"Ordena los pasos para rebasar a un ciclista con seguridad.","items":["Reducir y revisar el tráfico atrás","Señalar y revisar el carril contrario","Rebasar dejando 3 pies","Volver al carril cuando sea seguro"]},"ru":{"prompt":"Расставьте шаги безопасного обгона велосипедиста.","items":["Снизить скорость, проверить сзади","Включить сигнал, оценить встречную","Обогнать, оставив 3 фута","Вернуться на полосу, когда безопасно"]}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(7), 3, 60, $q${"en":"Motorcycles, trucks and railroad crossings","ja":"バイク・トラック・踏切","es":"Motos, camiones y cruces de ferrocarril","ru":"Мотоциклы, грузовики и ж/д переезды"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(7, 3), 1, 'rich_text', $q${"en":{"markdown":"Motorcycles are small and hard to see: check twice before turning or changing lanes and give them a full lane. Large trucks have big blind spots: if you cannot see the driver's mirror, the driver cannot see you. At a railroad crossing, stop if lights flash and never race a train."},"ja":{"markdown":"バイクは小さく見落としやすいので、右左折や車線変更の前に二度確認し、1車線分の余裕を与えます。大型トラックには大きな死角があり、運転者のミラーが見えなければ向こうからもあなたが見えません。踏切で警報が点滅していたら止まり、電車と競争してはいけません。"},"es":{"markdown":"Las motos son pequeñas y difíciles de ver: revisa dos veces antes de girar o cambiar de carril y dales un carril completo. Los camiones tienen grandes puntos ciegos: si no ves el espejo del conductor, él no te ve. En un cruce ferroviario, detente si las luces destellan y nunca compitas con un tren."},"ru":{"markdown":"Мотоциклы малы и плохо заметны: проверяйте дважды перед поворотом или перестроением и уступайте им целую полосу. У грузовиков большие слепые зоны: если вы не видите зеркало водителя, он не видит вас. На переезде остановитесь при мигающих огнях и не соревнуйтесь с поездом."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(7, 3), 2, 'callout', $q${"en":{"tone":"tip","title":"Trucks","markdown":"Do not cut in front of a truck: it needs much more distance to stop than a car."},"ja":{"tone":"tip","title":"トラック","markdown":"トラックの前に割り込まないでください。停止にはずっと長い距離が必要です。"},"es":{"tone":"tip","title":"Camiones","markdown":"No te cierres frente a un camión: necesita mucha más distancia para frenar."},"ru":{"tone":"tip","title":"Грузовики","markdown":"Не подрезайте грузовик: ему нужна гораздо большая дистанция для остановки."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(7, 3), 3, 'flip_card', $q${"en":{"front":"Railroad crossing with flashing lights","back":"Stop and wait. Never try to beat the train."},"ja":{"front":"点滅する踏切","back":"停止して待つ。電車より先に渡ろうとしない。"},"es":{"front":"Cruce con luces intermitentes","back":"Detente y espera. Nunca intentes ganarle al tren."},"ru":{"front":"Переезд с мигающими огнями","back":"Остановитесь и ждите. Не пытайтесь опередить поезд."}}$q$::jsonb);
