-- Section 8
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(8), 1, 60, $q${"en":"Points on your record","ja":"運転記録の違反点数","es":"Puntos en tu historial","ru":"Штрафные баллы"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(8, 1), 1, 'rich_text', $q${"en":{"markdown":"Most moving violations add one point to your driving record. A driver may be labeled a negligent operator with 4 points in 12 months, 6 in 24 months or 8 in 36 months, which can lead to suspension. Finishing a state-approved traffic school can keep a point off your public record, once every 18 months, if you are eligible."},"ja":{"markdown":"ほとんどの移動違反は運転記録に1点加算されます。12か月で4点、24か月で6点、36か月で8点になると不注意運転者とされ、免許停止の可能性があります。対象であれば、州認定の交通学校を修了することで、18か月に1回、公開記録への加点を避けられます。"},"es":{"markdown":"La mayoría de las infracciones de tránsito suman un punto a tu historial. Con 4 puntos en 12 meses, 6 en 24 o 8 en 36 se te considera conductor negligente y puedes ser suspendido. Terminar una escuela de tránsito aprobada puede evitar un punto en tu registro público, una vez cada 18 meses, si cumples los requisitos."},"ru":{"markdown":"Большинство нарушений добавляет один балл. При 4 баллах за 12 месяцев, 6 за 24 или 8 за 36 водителя считают небрежным, возможно лишение прав. Окончание одобренной штатом школы может избавить от балла в публичной записи раз в 18 месяцев, если вы подходите."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(8, 1), 2, 'flip_card', $q${"en":{"front":"Negligent operator","back":"4 points in 12 months, 6 in 24 or 8 in 36."},"ja":{"front":"不注意運転者","back":"12か月で4点、24か月で6点、36か月で8点。"},"es":{"front":"Conductor negligente","back":"4 puntos en 12 meses, 6 en 24 u 8 en 36."},"ru":{"front":"Небрежный водитель","back":"4 балла за 12 мес., 6 за 24 или 8 за 36."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(8, 1), 3, 'callout', $q${"en":{"tone":"info","title":"Check your eligibility","markdown":"Your court decides whether you may attend traffic school for your ticket. Confirm before you enroll."},"ja":{"tone":"info","title":"対象かどうか確認","markdown":"交通学校を利用できるかは裁判所が判断します。登録前に確認してください。"},"es":{"tone":"info","title":"Revisa tu elegibilidad","markdown":"El tribunal decide si puedes asistir a la escuela de tránsito. Confírmalo antes de inscribirte."},"ru":{"tone":"info","title":"Проверьте право","markdown":"Суд решает, можно ли вам пройти школу. Уточните до записи."}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(8), 2, 60, $q${"en":"If you are in a crash","ja":"事故に遭ったら","es":"Si tienes un choque","ru":"Если вы попали в аварию"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(8, 2), 1, 'rich_text', $q${"en":{"markdown":"Stop. Move to safety if you can, turn on hazard lights and check for injuries. Call 911 if anyone is hurt. Exchange name, address, license and insurance details. California requires you to report a crash to the DMV within 10 days if there was an injury or death, or more than $1,000 in damage."},"ja":{"markdown":"停止します。可能なら安全な場所へ移動し、ハザードを点けて負傷者を確認します。負傷者がいれば911に通報します。氏名、住所、免許、保険情報を交換します。負傷・死亡、または1,000ドル超の損害があった場合、10日以内にDMVへ報告が必要です。"},"es":{"markdown":"Detente. Muévete a un lugar seguro si puedes, enciende las intermitentes y revisa si hay heridos. Llama al 911 si alguien está herido. Intercambia nombre, dirección, licencia y seguro. California exige reportar al DMV en 10 días si hubo lesiones o muerte, o más de $1,000 en daños."},"ru":{"markdown":"Остановитесь. Если возможно, отъедите в безопасное место, включите аварийку и проверьте, нет ли пострадавших. При травмах звоните 911. Обменяйтесь именем, адресом, правами и данными страховки. Нужно сообщить в DMV в течение 10 дней, если были травмы или смерть либо ущерб свыше $1000."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(8, 2), 2, 'drag_to_order', $q${"en":{"prompt":"Order the steps after a crash.","items":["Stop and turn on hazard lights","Check for injuries and call 911 if needed","Exchange information","Report to the DMV within 10 days if required"]},"ja":{"prompt":"事故後の手順を並べてください。","items":["停止しハザードを点灯","負傷者を確認し必要なら911","情報を交換","必要なら10日以内にDMVへ報告"]},"es":{"prompt":"Ordena los pasos tras un choque.","items":["Detenerte y encender intermitentes","Revisar heridos y llamar al 911 si hace falta","Intercambiar información","Reportar al DMV en 10 días si se requiere"]},"ru":{"prompt":"Расставьте шаги после аварии.","items":["Остановиться, включить аварийку","Проверить пострадавших, при нужде 911","Обменяться данными","При необходимости сообщить в DMV в течение 10 дней"]}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(8, 2), 3, 'scenario', $q${"en":{"prompt":"You bump a parked car and the owner is not there. What do you do?","choices":[{"text":"Leave a note with my contact info and report it","feedback":"Right: you must try to notify the owner.","best":true},{"text":"Drive away","feedback":"That is a hit-and-run.","best":false},{"text":"Wait one minute, then leave","feedback":"Still not enough.","best":false}]},"ja":{"prompt":"駐車中の車に接触しましたが持ち主がいません。どうしますか?","choices":[{"text":"連絡先を書いたメモを残して届け出る","feedback":"正解: 持ち主に知らせる努力が必要です。","best":true},{"text":"立ち去る","feedback":"ひき逃げになります。","best":false},{"text":"1分待って立ち去る","feedback":"それでも不十分です。","best":false}]},"es":{"prompt":"Rozas un auto estacionado y el dueño no está. ¿Qué haces?","choices":[{"text":"Dejo una nota con mis datos y lo reporto","feedback":"Bien: debes intentar avisar al dueño.","best":true},{"text":"Me voy","feedback":"Eso es fuga del lugar.","best":false},{"text":"Espero un minuto y me voy","feedback":"Aún no es suficiente.","best":false}]},"ru":{"prompt":"Вы задели припаркованную машину, владельца нет. Что делаете?","choices":[{"text":"Оставляю записку с контактами и сообщаю","feedback":"Верно: нужно постараться уведомить владельца.","best":true},{"text":"Уезжаю","feedback":"Это оставление места ДТП.","best":false},{"text":"Жду минуту и уезжаю","feedback":"Этого недостаточно.","best":false}]}}$q$::jsonb);
insert into public.lessons (section_id, position, min_seconds, title) values (pg_temp.section_id(8), 3, 60, $q${"en":"Citations and your court date","ja":"違反切符と裁判所","es":"Citaciones y tu fecha en el tribunal","ru":"Штрафы и дата суда"}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(8, 3), 1, 'rich_text', $q${"en":{"markdown":"A citation lists your violation and a due date. Sign it (this is a promise to appear, not an admission), keep your copy and do not miss the deadline: missing it can add fines and a hold on your license. Contact the court to ask whether traffic school is possible."},"ja":{"markdown":"違反切符には違反内容と期限が記載されています。署名しますが、これは出頭の約束であり罪を認めるものではありません。控えを保管し、期限を守ってください。逃すと罰金が増え免許に制限がかかることがあります。交通学校が可能か裁判所に問い合わせます。"},"es":{"markdown":"Una citación indica tu infracción y una fecha límite. Fírmala (es una promesa de comparecer, no una admisión), guarda tu copia y no pierdas el plazo: puede sumar multas y un bloqueo en tu licencia. Pregunta al tribunal si puedes ir a escuela de tránsito."},"ru":{"markdown":"В штрафе указаны нарушение и срок. Подпишите (это обещание явиться, а не признание вины), сохраните копию и не пропускайте срок: иначе штрафы и ограничение прав. Спросите в суде, возможна ли школа."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(8, 3), 2, 'callout', $q${"en":{"tone":"warning","title":"Deadlines","markdown":"Finish the course before your court deadline so the court receives your completion in time."},"ja":{"tone":"warning","title":"期限","markdown":"裁判所の期限までに修了し、修了報告が間に合うようにしてください。"},"es":{"tone":"warning","title":"Plazos","markdown":"Termina el curso antes del plazo para que el tribunal reciba tu finalización a tiempo."},"ru":{"tone":"warning","title":"Сроки","markdown":"Завершите курс до срока суда, чтобы информация о завершении успела дойти."}}$q$::jsonb);
insert into public.lesson_blocks (lesson_id, position, type, content) values (pg_temp.lesson_id(8, 3), 3, 'flip_card', $q${"en":{"front":"What does signing a citation mean?","back":"A promise to appear, not an admission of guilt."},"ja":{"front":"違反切符への署名の意味は?","back":"出頭の約束であり、罪を認めることではない。"},"es":{"front":"¿Qué significa firmar una citación?","back":"Una promesa de comparecer, no admitir culpa."},"ru":{"front":"Что значит подпись на штрафе?","back":"Обещание явиться, а не признание вины."}}$q$::jsonb);
